// =============================================================================
// 场景：同一 TwinCAT 工程同时部署 C++ 模块 IncrementerCpp 的 v0.0.0.1 和
//       v0.0.0.2（不同产线用不同版本算法）。PLC 端按版本号实例化对应版本，
//       两个版本不能用同一 CLSID，否则 TwinCAT 无法区分要实例化哪个。
// 价值：手动给每版本各发一个 GUID 要 vendor 严格管理 GUID 表，乱了就编不
//       过；本函数确定性派生—同 lib id + clsId 永远得到相同结果，免维护表。
// 验证步骤：
//   1. 登录后 clsidVersionedResult 全 0，bComputeSucceeded = FALSE。
//   2. 在线把 clsidBaseFromCpp 的字段 Data1/Data2/Data3/Data4 写成模拟 GUID
//      （任意非零值；真实场景由 C++ 模块声明）。
//   3. 写 bComputeRequest := TRUE。
//   4. 观察 bComputeSucceeded = TRUE，clsidVersionedResult 被填入新 GUID。
//   5. 把 sCppModuleLibraryId 末尾 '0.0.0.1' 改成 '0.0.0.2'，重新触发，
//      clsidVersionedResult 完全不同——印证"版本影响派生结果"。
//   6. 错误演示：把 sCppModuleLibraryId 改成 'invalid_format'（缺 | 分隔），
//      bComputeSucceeded = FALSE——印证 §5 三段格式约束。
// =============================================================================

IF bComputeRequest THEN
    // 单次调用：sLibraryId 必须是严格的 '厂商|库名|版本' 三段
    bComputeSucceeded := F_GetClassIdVersioned(
        sLibraryId     := sCppModuleLibraryId,
        clsId          := clsidBaseFromCpp,
        clsIdVersioned := clsidVersionedResult);
    bComputeRequest := FALSE;
END_IF;
